def gen_formulas():
    # Generate clean candidate expressions over a, b, n, i, d and small constants
    atoms = ["a", "b", "n", "i", "d", "0", "1", "2", "3"]
    unary = ["a", "b", "n", "i", "d", "1", "2", "3", "-a", "-b", "a*2", "b*2", "a*3", "b*3",
             "a**2", "b**2", "a*n", "b*n", "a*i", "b*i", "a*d", "b*d", "a//2", "b//2", "a//b", "a%b", "b%a"]
    exprs = set(unary)
    ops = ["+", "-", "*", "//", "%"]
    for x in unary:
        for y in unary:
            for op in ops:
                if op in ("//", "%") and y in ("0", "d", "a*d", "b*d", "b//2"):
                    continue
                exprs.add(f"({x}) {op} ({y})")
    # Also 3-term +/- combinations of basic terms
    basic = ["a", "b", "n", "i", "d", "1", "2", "a*b", "a//b", "a%b", "a*2", "b*2", "a**2", "b**2", "abs(a-b)", "max(a,b)", "min(a,b)"]
    for x in basic:
        for y in basic:
            for op1 in ["+", "-"]:
                exprs.add(f"{x} {op1} {y}")
                for z in ["n", "i", "d", "1", "2", "a", "b"]:
                    for op2 in ["+", "-"]:
                        exprs.add(f"{x} {op1} {y} {op2} {z}")
    return sorted(exprs)

exprs = gen_formulas()
print("Total candidate formulas:", len(exprs))

